Here's a complete example:

**XAML**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">

        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem, Mode=TwoWay}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate>
                    <VerticalStackLayout Padding="10">
                        <Label Text="{Binding Name}" FontSize="18" />
                        <Label Text="{Binding Description}" FontSize="14"
                               TextColor="Gray" />
                    </VerticalStackLayout>
                </DataTemplate>
            </CollectionView.ItemTemplate>

            <CollectionView.EmptyView>
                <Label Text="No items found."
                       HorizontalOptions="Center"
                       VerticalOptions="Center" />
            </CollectionView.EmptyView>
        </CollectionView>
    </RefreshView>
</ContentPage>
```

**ViewModel** (using MVVM Community Toolkit)
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> _items = new();

    [ObservableProperty]
    private Item? _selectedItem;

    [ObservableProperty]
    private bool _isRefreshing;

    public ItemsViewModel(IApiService api, INavigationService nav)
    {
        _api = api;
        _nav = nav;
    }

    [RelayCommand]
    private async Task Refresh()
    {
        try
        {
            var data = await _api.GetItemsAsync();
            Items = new ObservableCollection<Item>(data);
        }
        finally
        {
            IsRefreshing = false; // stops the spinner
        }
    }

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;

        await _nav.NavigateToAsync(nameof(DetailPage),
            new Dictionary<string, object> { { "Item", SelectedItem } });

        SelectedItem = null; // reset so the same item can be re-selected
    }
}
```

**Key binding points:**

| XAML Property | ViewModel Property | Purpose |
|---|---|---|
| `RefreshView.IsRefreshing` | `IsRefreshing` | Shows/hides spinner; **must be set to `false`** when done |
| `RefreshView.Command` | `RefreshCommand` | Fires on pull-to-refresh |
| `CollectionView.SelectedItem` | `SelectedItem` (TwoWay) | Tracks current selection |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Fires on tap → navigates |

**Important details:**
- **Reset `SelectedItem` to `null`** after navigation, otherwise tapping the same item again won't fire the command.
- **Set `IsRefreshing = false`** in a `finally` block so the spinner always stops, even on errors.
- `SelectionMode="Single"` gives you one-at-a-time selection with a visual highlight. Use `"Multiple"` + `SelectedItems` if you need multi-select.
